<script>
const slides=[...document.querySelectorAll('.slide')];
let current=0;
function show(i){slides[current].classList.remove('active');current=(i+slides.length)%slides.length;slides[current].classList.add('active');}
window.addEventListener('keydown',(e)=>{if(e.key==='ArrowRight'||e.key==='PageDown')show(current+1);if(e.key==='ArrowLeft'||e.key==='PageUp')show(current-1);});
</script>
